import { ChevronRightIcon } from "lucide-react"
import { Item, ItemActions, ItemContent, ItemDescription, ItemGroup, ItemSeparator, ItemTitle } from "@kitora/ui/item"

export function ItemAsLink() {
  const [picked, setPicked] = useState("none")

  return (
    <div className="flex w-full max-w-md flex-col gap-2">
      <ItemGroup className="rounded-lg border" aria-label="Account">
        <Item interactive render={(props) => <a href="#profile" {...props}>{props.children}</a>} size="sm">
          <ItemContent>
            <ItemTitle>Profile</ItemTitle>
            <ItemDescription>A link: \`render={"<a href />"}\` gives it the hover fill and the focus ring.</ItemDescription>
          </ItemContent>
          <ItemActions>
            <ChevronRightIcon className="size-4 text-muted-foreground rtl:rotate-180" aria-hidden="true" />
          </ItemActions>
        </Item>
        <ItemSeparator />
        <Item render={<button type="button" onClick={() => setPicked("billing")} />} size="sm">
          <ItemContent>
            <ItemTitle>Billing</ItemTitle>
            <ItemDescription>A button: Enter and Space press it.</ItemDescription>
          </ItemContent>
          <ItemActions>
            <ChevronRightIcon className="size-4 text-muted-foreground rtl:rotate-180" aria-hidden="true" />
          </ItemActions>
        </Item>
        <ItemSeparator />
        <Item selected size="sm">
          <ItemContent>
            <ItemTitle>Security</ItemTitle>
            <ItemDescription>\`selected\` draws the list slot's selected fill; this row is plain text.</ItemDescription>
          </ItemContent>
        </Item>
        <ItemSeparator />
        <Item disabled size="sm">
          <ItemContent>
            <ItemTitle>Danger zone</ItemTitle>
            <ItemDescription>\`disabled\` dims the row and ignores the pointer.</ItemDescription>
          </ItemContent>
        </Item>
      </ItemGroup>
      <p className="text-xs text-muted-foreground">Button pressed: {picked}</p>
    </div>
  )
}
